import { useState } from 'react';
import {
  Button,
  Card,
  FormField,
  Input,
  Select,
  Stack,
  Switch,
} from '@jinx-ui/react';

export type Language = 'ru' | 'en';

export interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

export interface ProfileSettingsFormProps {
  initialSettings?: Partial<ProfileSettings>;
  onSave: (settings: ProfileSettings) => void;
}

const LANGUAGE_OPTIONS: { value: Language; label: string }[] = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

function ProfileSettingsForm({
  initialSettings,
  onSave,
}: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialSettings?.name ?? '');
  const [language, setLanguage] = useState<Language>(
    initialSettings?.language ?? 'ru',
  );
  const [emailNotifications, setEmailNotifications] = useState(
    initialSettings?.emailNotifications ?? false,
  );

  const trimmedName = name.trim();

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!trimmedName) return;
    onSave({ name: trimmedName, language, emailNotifications });
  };

  return (
    <Card>
      <form onSubmit={handleSubmit} noValidate>
        <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
          <FormField label="Имя" htmlFor="profile-name">
            <Input
              id="profile-name"
              name="name"
              value={name}
              autoComplete="name"
              onChange={(event) => setName(event.target.value)}
            />
          </FormField>

          <FormField label="Язык интерфейса" htmlFor="profile-language">
            <Select
              id="profile-language"
              name="language"
              value={language}
              onChange={(event) =>
                setLanguage(event.target.value as Language)
              }
            >
              {LANGUAGE_OPTIONS.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </Select>
          </FormField>

          <Switch
            id="profile-email-notifications"
            name="emailNotifications"
            label="Уведомления на почту"
            checked={emailNotifications}
            onChange={(event) =>
              setEmailNotifications(event.target.checked)
            }
          />

          <Button type="submit" variant="primary" disabled={!trimmedName}>
            Сохранить
          </Button>
        </Stack>
      </form>
    </Card>
  );
}

export default ProfileSettingsForm;

